export type PasskeyCeremonyKind = "registration" | "authentication";

/**
 * A server-side WebAuthn ceremony. The challenge is generated by the server, bound to the
 * tenant (and to a user or login challenge), single-use, and expires.
 */
export interface PasskeyCeremony {
  id: string;
  tenantId: string;
  kind: PasskeyCeremonyKind;
  /** base64url challenge that was returned in the creation or request options. */
  challenge: string;
  /** Registration only: the human user the new passkey is attached to. */
  userId: string | null;
  /** Authentication only: the login challenge this ceremony completes. */
  loginChallengeId: string | null;
  expiresAt: string;
  consumedAt: string | null;
  createdAt: string;
}

export interface PasskeyCredential {
  id: string;
  tenantId: string;
  userId: string;
  /** base64url WebAuthn credential ID. */
  credentialId: string;
  /** base64url COSE public key bytes, as returned by the registration verification. */
  publicKey: string;
  signCount: number;
  transports: string[] | null;
  deviceType: "singleDevice" | "multiDevice";
  backedUp: boolean;
  createdAt: string;
  updatedAt: string;
}

export interface PasskeyRepository {
  createCeremony(ceremony: PasskeyCeremony): Promise<void>;
  /**
   * Atomically marks an unexpired, unconsumed ceremony of the given kind as consumed.
   * Returns the ceremony, or null when it is missing, expired, already consumed, or of another kind.
   */
  consumeCeremony(
    id: string,
    kind: PasskeyCeremonyKind,
    now: string
  ): Promise<PasskeyCeremony | null>;
  createCredential(credential: PasskeyCredential): Promise<void>;
  findCredentialByCredentialId(tenantId: string, credentialId: string): Promise<PasskeyCredential | null>;
  listCredentialsByUserId(tenantId: string, userId: string): Promise<PasskeyCredential[]>;
  /** Stores the signature counter and backup state reported by a verified assertion. */
  updateCredentialAfterAssertion(
    id: string,
    update: { signCount: number; backedUp: boolean; updatedAt: string }
  ): Promise<void>;
}
